// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Check the username and password, then start a session.
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session. The session row is deleted and the cookie is cleared.
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe The user of the current session. Requires a session cookie.
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListClaims List claims in a scope (F-03, F-04, F-08).
	// (GET /claims)
	ListClaims(ctx context.Context, request ListClaimsRequestObject) (ListClaimsResponseObject, error)
	// CreateClaim Create a claim and submit it for review, or save it as a draft (F-02, F-05).
	// (POST /claims)
	CreateClaim(ctx context.Context, request CreateClaimRequestObject) (CreateClaimResponseObject, error)
	// DeleteClaim Delete a draft and its line items (F-05).
	// (DELETE /claims/{id})
	DeleteClaim(ctx context.Context, request DeleteClaimRequestObject) (DeleteClaimResponseObject, error)
	// GetClaim A visible claim with its line items, history, and the actions the session user may take (F-03).
	// (GET /claims/{id})
	GetClaim(ctx context.Context, request GetClaimRequestObject) (GetClaimResponseObject, error)
	// UpdateClaim Edit a draft or returned claim (F-05).
	// (PUT /claims/{id})
	UpdateClaim(ctx context.Context, request UpdateClaimRequestObject) (UpdateClaimResponseObject, error)
	// ApproveClaim Approve a submitted claim (F-04, F-08).
	// (POST /claims/{id}/approve)
	ApproveClaim(ctx context.Context, request ApproveClaimRequestObject) (ApproveClaimResponseObject, error)
	// FinalApproveClaim Make the final approval of a claim pending finance (F-08).
	// (POST /claims/{id}/final-approve)
	FinalApproveClaim(ctx context.Context, request FinalApproveClaimRequestObject) (FinalApproveClaimResponseObject, error)
	// FinalRejectClaim Make the final rejection of a claim pending finance (F-08).
	// (POST /claims/{id}/final-reject)
	FinalRejectClaim(ctx context.Context, request FinalRejectClaimRequestObject) (FinalRejectClaimResponseObject, error)
	// RejectClaim Reject a submitted claim with a reason (F-04).
	// (POST /claims/{id}/reject)
	RejectClaim(ctx context.Context, request RejectClaimRequestObject) (RejectClaimResponseObject, error)
	// ReturnClaim Return a submitted claim to its requester with a reason (F-06).
	// (POST /claims/{id}/return)
	ReturnClaim(ctx context.Context, request ReturnClaimRequestObject) (ReturnClaimResponseObject, error)
	// SubmitClaim Submit a draft for review (F-05).
	// (POST /claims/{id}/submit)
	SubmitClaim(ctx context.Context, request SubmitClaimRequestObject) (SubmitClaimResponseObject, error)
	// WithdrawClaim Withdraw a submitted or returned claim (F-07).
	// (POST /claims/{id}/withdraw)
	WithdrawClaim(ctx context.Context, request WithdrawClaimRequestObject) (WithdrawClaimResponseObject, error)
	// GetHealth Liveness. Does not use the database.
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetReady Readiness. Returns 503 when the database is unreachable.
	// (GET /ready)
	GetReady(ctx context.Context, request GetReadyRequestObject) (GetReadyResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

